function build(api) {
  api.name('Pikachu');
  const C_YELLOW = 0xFFD700, C_DARK_Y = 0xE6C200, C_BLACK = 0x111111, C_RED = 0xCC3333, C_BROWN = 0x8B4513, C_EYE = 0x222222;

  api.group('body', '躯干');
    api.group('chest', '胸');
      api.box({w:2.2, h:1.8, d:1.6, pos:[0,3.5,0], color:C_YELLOW});
    api.endGroup();
    api.group('abdomen', '腹');
      api.box({w:2.0, h:1.2, d:1.5, pos:[0,2.2,0], color:C_YELLOW});
    api.endGroup();
    api.group('pelvis', '胯');
      api.box({w:2.2, h:0.8, d:1.6, pos:[0,1.3,0], color:C_YELLOW});
    api.endGroup();
    api.box({w:1.6, h:0.06, d:0.8, pos:[0,4.0,-0.85], color:C_BROWN});
    api.box({w:1.6, h:0.06, d:0.8, pos:[0,3.3,-0.85], color:C_BROWN});
  api.endGroup();

  api.group('head', '头部');
    api.sphere({r:1.3, pos:[0,5.5,0], color:C_YELLOW});
    api.box({w:1.8, h:0.8, d:0.9, pos:[0,5.1,0.95], color:C_YELLOW});
    api.box({w:1.6, h:0.5, d:0.6, pos:[0,4.85,1.2], color:C_YELLOW});
    api.box({w:1.8, h:0.15, d:0.95, pos:[0,4.7,0.95], color:C_BROWN});
    api.poly({r:0.25, pos:[0.65,5.2,1.25], color:C_RED});
    api.poly({r:0.25, pos:[-0.65,5.2,1.25], color:C_RED});
    api.poly({r:0.22, pos:[0.4,5.65,1.15], color:C_EYE});
    api.poly({r:0.22, pos:[-0.4,5.65,1.15], color:C_EYE});
    api.poly({r:0.06, pos:[0.48,5.72,1.2], color:0xFFFFFF});
    api.poly({r:0.06, pos:[-0.32,5.72,1.2], color:0xFFFFFF});
    api.group('leftEar', '左耳');
      api.chain({waypoints:[[-0.5,6.5,0],[-0.7,7.8,-0.2],[-0.8,8.8,-0.3]], r:0.25, rEnd:0.2, jointIds:['earBase','earMid','earTip'], color:C_YELLOW});
      api.cone({r:0.25, h:0.6, along:'-Y', pos:[-0.8,9.1,-0.3], color:C_BLACK});
    api.endGroup();
    api.group('right Ear', '右耳');
      api.chain({waypoints:[[0.5,6.5,0],[0.7,7.8,-0.2],[0.8,8.8,-0.3]], r:0.25, rEnd:0.2, jointIds:['earBase','earMid','earTip'], color:C_YELLOW});
      api.cone({r:0.25, h:0.6, along:'-Y', pos:[0.8,9.1,-0.3], color:C_BLACK});
    api.endGroup();
  api.endGroup();

  api.mirror('x');
  api.group('leftArm', '左臂');
    api.chain({waypoints:[[-1.3,3.5,0],[-1.6,2.8,0.2],[-1.5,2.2,0.3]], r:0.3, rEnd:0.25, jointIds:['upperArm','forearm','hand'], color:C_YELLOW});
  api.endGroup();
  api.endMirror();

  api.group('rightArm', '右臂');
    api.chain({waypoints:[[1.3,3.5,0],[1.6,2.8,0.2],[1.5,2.2,0.3]], r:0.3, rEnd:0.25, jointIds:['upperArm','forearm','hand'], color:C_YELLOW});
  api.endGroup();

  api.mirror('x');
  api.group('leftLeg', '左腿');
    api.chain({waypoints:[[-0.6,1.0,0],[-0.6,0.5,0.1],[-0.6,0.15,0.3]], r:0.4, rEnd:0.45, jointIds:['thigh','shin','foot'], color:C_YELLOW});
    api.box({w:0.7, h:0.15, d:0.8, pos:[-0.6,0.08,0.4], color:C_BROWN});
  api.endGroup();
  api.endMirror();

  api.group('rightLeg', '右腿');
    api.chain({waypoints:[[0.6,1.0,0],[0.6,0.5,0.1],[0.6,0.15,0.3]], r:0.4, rEnd:0.45, jointIds:['thigh','shin','foot'], color:C_YELLOW});
    api.box({w:0.7, h:0.15, d:0.8, pos:[0.6,0.08,0.4], color:C_BROWN});
  api.endGroup();

  api.group('tail', '尾巴');
    api.chain({waypoints:[[0,2.8,-0.9],[0,3.5,-1.8],[0,4.5,-1.5],[0,4.0,-2.5],[0,5.0,-2.2]], r:0.3, rEnd:0.2, jointIds:['tail1','tail2','tail3','tail4','tail5'], color:C_YELLOW});
    api.cone({r:0.35, h:0.8, along:'+Y', pos:[0,5.4,-2.2], color:C_YELLOW});
    api.box({w:0.5, h:0.06, d:0.5, pos:[0,3.5,-1.85], color:C_BROWN});
  api.endGroup();
}
